        self,
        key: str,
        device: torch.device | None = None,
        optional: bool = False,
        allow_bf16: bool = False
    ) -> torch.Tensor | None:

        file = None
        for k, v in self.tensor_map_sort:
            if key.startswith(k):
                file = v
