        res = [stc.get_metrics() for stc in self.stcs.values()]
        bytes_loaded = sum(r[0] for r in res)
        time_elapsed = sum(r[1] for r in res)
        bandwidth = bytes_loaded / (1024**3) / time_elapsed
        return bytes_loaded, time_elapsed, bandwidth
